    accesses: list[_Access] = []
    for item in raw:
        if not isinstance(item, dict):
            raise InvalidAccess("each access must be an object")
        accesses.append(_Access(item))
    return accesses


def _covers(consent: _Consent, access: _Access) -> bool:
    return (
